const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const app = express();

// Security middleware
app.use(helmet());
app.use(cors({ origin: process.env.ALLOWED_ORIGINS || '*' }));

// Parse JSON bodies with a size limit
app.use(express.json({ limit: '10kb' }));

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack);
  res.status(500).json({ error: 'Internal Server Error' });
});

// Route for health check
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Route for retrieving users with optional filtering
app.get('/users', (req, res) => {
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];

  try {
    // Validate query parameters (basic example)
    if (req.query.id && isNaN(parseInt(req.query.id))) {
      return res.status(400).json({ error: 'Invalid user ID' });
    }

    // Filter users based on query parameters
    let filteredUsers = users;
    if (req.query.id) {
      const userId = parseInt(req.query.id);
      filteredUsers = users.filter(user => user.id === userId);
    }

    res.json(filteredUsers);
  } catch (error) {
    console.error('Error fetching users:', error.message);
    res.status(500).json({ error: 'Internal Server Error' });
  }
});

// 404 handler for undefined routes
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Validate environment variables
const validateEnv = () => {
  const envs = ['PORT', 'ALLOWED_ORIGINS', 'DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY'];
  const missing = envs.filter(env => !process.env[env]);
  if (missing.length > 0) {
    console.warn(`Missing environment variables: ${missing.join(', ')}`);
  }
};

// Start the server
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  validateEnv();
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;

